'use strict';

// MODULES //

var tape = require( 'tape' );
var fromMarkdown = require( '@stdlib/_tools/semantic-document/from-markdown' );
var toIPYNB = require( './../lib' );


// FUNCTIONS //

/**
* Returns the first semantic node of a specified type.
*
* @private
* @param {Array} children - semantic children
* @param {string} type - node type
* @returns {(Object|null)} semantic node
*/
function findNode( children, type ) {
	var out;
	var i;

	for ( i = 0; i < children.length; i++ ) {
		if ( children[ i ].type === type ) {
			return children[ i ];
		}
		if ( children[ i ].children ) {
			out = findNode( children[ i ].children, type );
			if ( out ) {
				return out;
			}
		}
	}
	return null;
}

/**
* Creates a tutorial semantic document.
*
* @private
* @param {string} body - tutorial body
* @param {boolean} [slices] - boolean indicating whether to retain source slices
* @returns {Object} semantic document
*/
function tutorial( body, slices ) {
	return fromMarkdown( '# Example\n\n> Example summary.\n\n'+body, {
		'includeSourceSlices': slices === true,
		'mode': 'strict',
		'profile': 'tutorial'
	});
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof toIPYNB, 'function', 'main export is a function' );
	t.end();
});

tape( 'the converter renders frontmatter, thematic breaks, math, and HTML raw content', function test( t ) {
	var markdown = [
		'---',
		'name: example',
		'---',
		'',
		'# Example',
		'',
		'> Example summary.',
		'',
		'---',
		'',
		'```math',
		'x^2',
		'```',
		'',
		'<div>visual</div>'
	].join( '\n' );
	var notebook;
	var source;
	var doc;

	doc = fromMarkdown( markdown, {
		'mode': 'strict',
		'profile': 'tutorial'
	});
	notebook = toIPYNB( doc );
	source = notebook.cells.map( function getSource( cell ) {
		return cell.source.join( '' );
	}).join( '\n' );

	t.ok( source.indexOf( '```yaml\nname: example\n```' ) >= 0, 'renders frontmatter as fenced Markdown' );
	t.ok( source.indexOf( '$$\nx^2\n$$' ) >= 0, 'renders display math for MathJax' );
	t.ok( source.indexOf( '<div>visual</div>' ) >= 0, 'keeps HTML in rendered Markdown' );
	t.ok( findNode( doc.children, 'thematicBreak' ), 'source includes a semantic thematic break' );
	t.end();
});

tape( 'the converter preserves exact executable source when no lowering is needed', function test( t ) {
	var notebook;
	var values = [ '', '1;', '1;\n', '1;\r\n2;' ];
	var code;
	var doc;
	var i;

	for ( i = 0; i < values.length; i++ ) {
		doc = tutorial( '```javascript\n1;\n```' );
		code = findNode( doc.children, 'code' );
		code.value = values[ i ];
		notebook = toIPYNB( doc );
		t.strictEqual( notebook.cells[ notebook.cells.length-1 ].source.join( '' ), values[ i ], 'preserves exact source case '+i );
	}
	t.end();
});

tape( 'lowered provenance distinguishes semantic code from the authored Markdown slice', function test( t ) {
	var notebook;
	var source;
	var code;
	var doc;

	source = "var abs = require( '@stdlib/math/base/special/abs' );";
	doc = tutorial( '```javascript\n'+source+'\n```', true );
	notebook = toIPYNB( doc, {
		'includeProvenance': true
	});
	code = notebook.cells[ notebook.cells.length-1 ];

	t.strictEqual( code.metadata.stdlib.pre_transform_source, source, 'retains semantic pre-transform code' );
	t.strictEqual( code.metadata.stdlib.authored_source_slice, '```javascript\n'+source+'\n```', 'retains the authored fenced slice separately' );
	t.end();
});

tape( 'unsupported portable MDAST follows strict and permissive rendering policy', function test( t ) {
	var markdown;
	var notebook;
	var doc;
	var err;

	doc = tutorial( 'Paragraph.\n\n```javascript\n1;\n```' );
	markdown = findNode( doc.children, 'markdown' );
	markdown.ast = {
		'type': 'root',
		'children': [
			{
				'type': 'not-supported-by-remark'
			}
		]
	};
	try {
		toIPYNB( doc );
	} catch ( error ) {
		err = error;
	}
	t.ok( err && err.notebook, 'strict mode rejects unsupported MDAST with a partial notebook' );
	notebook = toIPYNB( doc, {
		'mode': 'permissive'
	});
	t.ok( notebook.cells.some( function hasPlaceholder( cell ) {
		return cell.source.join( '' ).indexOf( 'Unsupported semantic content omitted' ) >= 0;
	}), 'permissive mode emits a visible placeholder' );
	t.end();
});
